js.text:

function grid$sysrighthr(f){
  this.constructor(f);
}
grid$sysrighthr.prototype = new DirEvent();
grid$sysrighthr.prototype.afterInit = function(){
  var p = this._dir;
  p.options.buttonGridKeys[69] = 'permission';
  if (p.options._xtype == 1)
    p.options.dirController = 'sysuserinfo';
  else
    p.options.dirController = 'sysgroupinfo';
}
grid$sysrighthr.prototype.formActionChange = function(action, m){
  var p = this._dir;
  if (p.options._xtype == 0 && action == 'BeforeShowViewDir') {
    m.get('user_id').Name = 'group_id';
  }
  return true;
}
grid$sysrighthr.prototype.beforeButtonGridClick = function(id, gindex){
  var p = this._dir, dt = p.grid().data;
  if (id == 'permission') {
    var r = p.curr("r", undefined, gindex);
    if (r != null) {
      p.request('CheckRight', '', [['user_id', 'C', dt.val(r, 'user_id')]], function(p, d, run){
        if (run) {
          p.showFilter('hrpermission', null, {backdropclick: false});
        }
      })
      return false;
    }
  }
  return true
}

css.text:

.toolbar-close > div {
	background-position: -336px -400px !important;
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
